CREATE TABLE IF NOT EXISTS fixtures(id INTEGER PRIMARY KEY, league INTEGER NOT NULL, kickoff INTEGER NOT NULL, finished INTEGER NOT NULL, data TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS fixtures_league_time ON fixtures(league,kickoff);
CREATE TABLE IF NOT EXISTS forecasts(id INTEGER PRIMARY KEY AUTOINCREMENT, fixture_id INTEGER NOT NULL, version TEXT NOT NULL, phase TEXT NOT NULL CHECK(phase IN ('preliminary','final')), created_at INTEGER NOT NULL, kickoff INTEGER NOT NULL, data TEXT NOT NULL, UNIQUE(fixture_id,phase,version), CHECK(created_at<kickoff));
CREATE TRIGGER IF NOT EXISTS immutable_forecasts BEFORE UPDATE ON forecasts BEGIN SELECT RAISE(ABORT,'forecasts are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_forecasts_delete BEFORE DELETE ON forecasts BEGIN SELECT RAISE(ABORT,'forecasts are immutable'); END;
CREATE INDEX IF NOT EXISTS forecast_fixture ON forecasts(fixture_id);
CREATE TABLE IF NOT EXISTS results(fixture_id INTEGER PRIMARY KEY,hg INTEGER NOT NULL,ag INTEGER NOT NULL,settled_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS cache(key TEXT PRIMARY KEY,data TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS quota(day TEXT PRIMARY KEY,n INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS locks(key TEXT PRIMARY KEY,until INTEGER NOT NULL);
